create policy fleet_metric_definitions_admin_or_fleet_read on public.fleet_metric_definitions for select to authenticated using (public.is_platform_owner(auth.uid()) or public.fleet_metric_controller_authorized(business_id)); create policy fleet_metric_assignments_admin_or_fleet_read on public.fleet_metric_assignments for select to authenticated using (public.is_platform_owner(auth.uid()) or public.fleet_metric_controller_authorized((select md.business_id from public.fleet_metric_definitions md where md.id=fleet_metric_assignments.metric_definition_id))); create policy fleet_operational_events_admin_or_member_read on public.fleet_operational_events for select to authenticated using (public.is_platform_owner(auth.uid()) or business_id in (select business_id from public.business_members where user_id=auth.uid())); create policy leaderboard_rewards_authenticated_read on public.leaderboard_rewards for select to authenticated using (true); create policy network_leaderboard_participation_actor_or_admin_read on public.network_leaderboard_participation for select to authenticated using (actor_id=auth.uid() or public.is_platform_owner(auth.uid()));
